// 피사체 목록에 경로를 입힌다 (맵 목록과 추가 피사체가 모두 만들어진 뒤에 부른다)
export function applyRoutes(maps) {
  for (const m of maps) {
    const R = ROUTES[m.id];
    if (!R) continue;
    for (const t of m.tracking) if (R[t.id]) Object.assign(t, R[t.id]);
  }
}
